mapper.select:
SELECT `${column.name}`
FROM `${table}` WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId}
AND `${watermark}` >= #{since}
AND `${key}` > #{cursor}
ORDER BY `${key}` LIMIT 200

SELECT COALESCE(SUM(on_hand_qty),0) on_hand, COALESCE(SUM(reserved_qty),0) reserved,
    COALESCE(SUM(free_execution_claim_qty),0) claimed FROM stock_balance
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId}
